import {memo,useId} from 'react';
import {HOMEWORLD_NATIVE_CATALOGUE_V81} from './systems/homeworldNativeArchitectureV81';
import {homeworldRetainingRenderV82,type HomeworldRetainingSupportV82} from './systems/homeworldRetainingAssembliesV82';
import {HOMEWORLD_GEOMETRY_V64} from './systems/homeworldGeometryV64';
import {homeworldLevelV77} from './systems/homeworldWorldV77';
import {homeworldSceneDepthV78} from './systems/homeworldVisualLayersV78';

/** These masonry masses render the exact solid polygons registered by the
 * collision model. They are authored volumes, not additional generated PNGs.
 * Native material sources remain unchanged and do not grant extra ground. */
export default memo(function HomeworldRetainingSupportV82({support,camera}:{
 support:HomeworldRetainingSupportV82;camera:{x:number;y:number;viewWidth:number;viewHeight:number};
}){
 const uid=useId().replace(/:/g,'-'),elevation=homeworldLevelV77(support.levelId).elevation;
 const shape=homeworldRetainingRenderV82(support,HOMEWORLD_GEOMETRY_V64.depthScale,elevation);
 const points=shape.faces.flatMap(face=>face.polygon),left=Math.min(...points.map(p=>p.x)),top=Math.min(...points.map(p=>p.y));
 const width=Math.max(...points.map(p=>p.x))-left,height=Math.max(...points.map(p=>p.y))-top;
 if(left+width<camera.x-160||left>camera.x+camera.viewWidth+160||top+height<camera.y-160||top>camera.y+camera.viewHeight+160)return null;
 const wall=HOMEWORLD_NATIVE_CATALOGUE_V81.assets['basalt-city-foundation'].art;
 const cap=HOMEWORLD_NATIVE_CATALOGUE_V81.assets['paving-undercity'].art;
 const vertices=(ps:readonly {x:number;y:number}[])=>ps.map(p=>`${p.x},${p.y}`).join(' ');
 const faces=[...shape.faces].sort((a,b)=>a.polygon.reduce((sum,p)=>sum+p.y,0)-b.polygon.reduce((sum,p)=>sum+p.y,0));
 return <svg aria-hidden="true" data-homeworld-retaining-support-v82={support.id} data-structural-owner-v82={support.ownerId}
  data-volume-source-v82={support.nativeStatus} data-world-level-v77={support.levelId}
  width={width+4} height={height+4} viewBox={`${left-2} ${top-2} ${width+4} ${height+4}`}
  style={{position:'absolute',left:left-2,top:top-2,zIndex:homeworldSceneDepthV78(shape.depth,elevation),pointerEvents:'none'}}>
  <defs>
   <pattern id={uid+'-wall'} width="420" height={420*wall.sourceHeight/wall.sourceWidth} patternUnits="userSpaceOnUse"><image href={wall.src} width="420" height={420*wall.sourceHeight/wall.sourceWidth} preserveAspectRatio="xMidYMin meet"/></pattern>
   <pattern id={uid+'-cap'} width="180" height={180*HOMEWORLD_GEOMETRY_V64.depthScale} patternUnits="userSpaceOnUse"><image href={cap.src} width="180" height={180*HOMEWORLD_GEOMETRY_V64.depthScale} preserveAspectRatio="none"/></pattern>
  </defs>
  {faces.map(face=><g key={face.id}>
   <polygon points={vertices(face.polygon)} fill="#231b15"/>
   <polygon points={vertices(face.polygon)} fill={`url(#${uid}-wall)`} stroke="#71593b" strokeWidth="1.5"/>
  </g>)}
  <polygon points={vertices(shape.top)} fill="#40362a"/>
  <polygon points={vertices(shape.top)} fill={`url(#${uid}-cap)`} stroke="#a78a5c" strokeWidth="2"/>
 </svg>;
});

"use client";

import { useMemo, useState } from "react";
import type { WarPlanetV96 } from "./systems/clanWarPlanetsV96";
import type { PlanetReliefRasterV150 } from "./systems/clanWarPlanetReliefV150";
import type { PlanetTerrainSlopeV152 } from "./systems/clanWarPlanetTerrainV152";
import { warUnitV85 } from "./systems/clanWarV85Data";
import { analyzePlanetTraverseSectionV155 } from "./systems/clanWarPlanetTraverseSectionV155";
import {
  PLANET_MOBILITY_PROFILES_V154, buildPlanetTraversalGridV154,
  preferredTraversalStartV154, isTraversalCellPassableV154,
  planPlanetTraversalV154, createPlanetTraversalSessionV154,
  commitPlanetTraversalPlanV154, advancePlanetTraversalV154,
  type PlanetTraversalGridV154, type PlanetMobilityUnitIdV154,
  type PlanetTraversalSessionV154,
} from "./systems/clanWarPlanetTraverseV154";
import styles from "./PlanetTraversalLabV154.module.css";

function exportTraversalV154(value:unknown,name:string) {
  const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+"\n"],{type:"application/json"}));
  const link=document.createElement("a");
  link.href=url;link.download=name;document.body.appendChild(link);
  try{link.click();}finally{link.remove();window.setTimeout(()=>URL.revokeObjectURL(url),30000);}
}

/** A genuine interactive movement simulation on existing V150 source pixels,
 * isolated from the actual war order and mission autosave systems. */
function WalkOnPlanetV154({grid,territoryName}:{
  grid:PlanetTraversalGridV154;territoryName:string;
}) {
  const [unitId,setUnitId]=useState<PlanetMobilityUnitIdV154>("RTS-U02");
  const [session,setSession]=useState<PlanetTraversalSessionV154>(
    ()=>createPlanetTraversalSessionV154(grid,"RTS-U02"));
  const [status,setStatus]=useState("Choisissez une case terrestre à atteindre.");
  const sourceUnit=warUnitV85(unitId);
  const currentProfile=PLANET_MOBILITY_PROFILES_V154.find(profile=>profile.unitTypeId===unitId)!;
  const crossSection=analyzePlanetTraverseSectionV155(grid,session);
  const svgWidth=640,svgHeight=154,svgPadding=24;
  const altitudeRange=Math.max(1,crossSection.maxElevationMeters-crossSection.minElevationMeters);
  const chartCoords=crossSection.nodes.map((node,index)=>({
    x:crossSection.totalDistanceKm>0?
      svgPadding+(node.distanceFromStartKm/crossSection.totalDistanceKm)*(svgWidth-2*svgPadding):
      svgWidth/2,
    y:svgHeight-svgPadding-
      ((node.elevationMeters-crossSection.minElevationMeters)/altitudeRange)*(svgHeight-2*svgPadding),
    index,
  }));
  const line=chartCoords.map(p=>p.x+","+p.y).join(" ");
  const area=chartCoords.length?
    `M ${chartCoords[0].x} ${svgHeight-svgPadding} L ${chartCoords.map(p=>p.x+" "+p.y).join(" L ")} L ${chartCoords.at(-1)!.x} ${svgHeight-svgPadding} Z`:"";
  const marker=chartCoords[crossSection.currentNodeIndex]??null;
  const queued=new Set(session.queued.map(p=>p.x+","+p.y));
  const visited=new Set(session.walked.map(p=>p.x+","+p.y));
  const blocked=grid.cells.filter(cell=>!isTraversalCellPassableV154(cell,unitId)).length;
  const selectProfile=(next:PlanetMobilityUnitIdV154)=>{
    setUnitId(next);setSession(createPlanetTraversalSessionV154(grid,next));
    setStatus("Unité sélectionnée : carte et position de départ recalculées.");
  };
  const plan=(x:number,y:number)=>{
    if(!session.position){setStatus("Aucune zone terrestre praticable pour cette unité dans le secteur.");return;}
    const result=planPlanetTraversalV154(grid,session.position,{x,y},unitId);
    if(result.status==="reachable"){
      setSession(commitPlanetTraversalPlanV154(session,grid,result));
      setStatus("Chemin préparé : "+(result.path.length-1)+" case(s), "+
        result.distanceKm.toLocaleString("fr-FR")+" km cartographiques estimés. Confirmez les pas.");
    } else if(result.status==="already-there"){
      setStatus("Cette case est déjà occupée.");
    } else if(result.status==="blocked"){
      setStatus("Destination interdite : milieu non terrestre ou pente trop forte pour cette unité.");
    } else {
      setStatus("Aucune traversée terrestre continue : aucun pont ou raccourci n’est créé.");
    }
  };
  const advance=()=>setSession(current=>advancePlanetTraversalV154(current,grid));
  const finish=()=>{
    let current=session,steps=0;
    while(current.queued.length&&steps++<=grid.width*grid.height){
      const next=advancePlanetTraversalV154(current,grid);
      if(next===current)break;
      current=next;
    }
    setSession(current);
    setStatus(current.queued.length?"Le passage est interrompu.":"Détachement arrivé à la case cible.");
  };
  const reset=()=>{
    setSession(createPlanetTraversalSessionV154(grid,unitId));
    setStatus("Exercice réinitialisé, sans modification du front.");
  };
  const save=()=>{
    try{
      exportTraversalV154({
        ...session,
        format:"yautja-planet-traversal-session",
        sectorTerritory:territoryName,
        grid:{width:grid.width,height:grid.height,samplePixels:grid.samplePixels,
          radiusKm:grid.radiusKm,center:grid.center},
        unitName:sourceUnit?.name??unitId,maximumAllowedGradePercent:currentProfile.maxGradePercent,
        blockedCells:blocked,
        terrainElevationProfileV155:crossSection,
        limitations:[...grid.limitations,
          "Local path and travelled cells are an editor exercise, never a campaign/war transaction."],
      },grid.worldCode+"-traversal-v154.json");
      setStatus("Exercice exporté en JSON ; aucun combattant de la partie n’a été déplacé.");
    }catch{setStatus("Export de l’exercice indisponible.");}
  };
  return <div className={styles.play} data-testid="planet-traversal-play-v154"
    data-world-code={grid.worldCode} data-unit-id={unitId} data-steps={session.steps}
    data-position={session.position?session.position.x+","+session.position.y:"none"}>
    <div className={styles.toolbar}>
      <label>Unité réelle du roster des clans
        <select data-testid="planet-traversal-unit-v154" value={unitId}
          onChange={event=>selectProfile(event.target.value as PlanetMobilityUnitIdV154)}>
          {PLANET_MOBILITY_PROFILES_V154.map(profile=><option key={profile.unitTypeId} value={profile.unitTypeId}>
            {profile.unitTypeId} · {warUnitV85(profile.unitTypeId)?.name??profile.unitTypeId}
          </option>)}
        </select>
      </label>
      <div className={styles.unitInfo} data-testid="planet-traversal-profile-v154">
        <strong>{sourceUnit?.name??unitId}</strong>
        <p>Limite de pente provisoire : {currentProfile.maxGradePercent} %.
          {sourceUnit?.terrain?" "+sourceUnit.terrain:""} Les obstacles d’eau ou de milieu restent infranchissables sans passage préalablement prévu.</p>
      </div>
    </div>
    <p>Départ : {territoryName}. Chaque case provient du raster géographique V150 de cette planète ; à cette résolution globale, elle peut représenter plusieurs kilomètres. Ce n’est pas encore une collision locale à l’échelle d’un personnage.</p>
    <div className={styles.gridScroll}>
      <div className={styles.board} role="group" aria-label="Carte interactive des passages et pentes"
        data-testid="planet-traversal-map-v154"
        style={{gridTemplateColumns:`repeat(${grid.width},minmax(22px,1fr))`}}>
        {grid.cells.map(cell=>{
          const position=session.position?.x===cell.x&&session.position.y===cell.y;
          const key=cell.x+","+cell.y;
          const passable=isTraversalCellPassableV154(cell,unitId);
          const planned=queued.has(key),wasHere=visited.has(key);
          return <button key={key} type="button" className={styles.tile}
            data-testid="planet-traversal-tile-v154" data-x={cell.x} data-y={cell.y}
            data-land={cell.land} data-passable={passable} data-region={cell.regionIndex}
            data-planned={planned} data-current={position}
            data-visited={wasHere} data-outside={cell.outside}
            aria-label={`Case ${cell.x}, ${cell.y} · ${cell.outside?"hors de la planète":!cell.land?"milieu non terrestre":cell.gradePercent.toFixed(2)+" pour cent de pente"}`}
            aria-current={position?"location":undefined}
            onClick={()=>plan(cell.x,cell.y)} title={`Altitude ${cell.elevationMeters} m · pente ${cell.gradePercent.toFixed(2)} %`}>
            {position?"◆":planned?"●":wasHere?"·":cell.outside?"":!cell.land?"≈":passable?"·":"▲"}
          </button>;
        })}
      </div>
    </div>
    <div className={styles.elevationSection} data-testid="planet-traversal-section-v155"
      data-points={crossSection.nodes.length} data-current-index={crossSection.currentNodeIndex}
      data-distance-km={crossSection.totalDistanceKm}>
      <strong>Profil d’altitude de l’itinéraire en cours</strong>
      <svg viewBox={`0 0 ${svgWidth} ${svgHeight}`} role="img"
        aria-label="Coupe du relief réel V150 sous le parcours choisi">
        <line x1={svgPadding} x2={svgWidth-svgPadding} y1={svgHeight-svgPadding}
          y2={svgHeight-svgPadding} stroke="#6d9884" strokeWidth="1"/>
        {area&&<path d={area} fill="#376451" fillOpacity=".6"/>}
        {line&&<polyline points={line} stroke="#d8d39d" fill="none"
          strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>}
        {marker&&<circle cx={marker.x} cy={marker.y} r={7}
          fill="#f6d793" stroke="#132923" strokeWidth="3"/>}
      </svg>
      <div className={styles.sectionFacts}>
        <span>{crossSection.nodes.length} point(s) du trajet</span>
        <span>Montée : {crossSection.ascentMeters.toLocaleString("fr-FR")} m</span>
        <span>Descente : {crossSection.descentMeters.toLocaleString("fr-FR")} m</span>
        <span>Altitude min./max. : {crossSection.minElevationMeters.toLocaleString("fr-FR")} / {crossSection.maxElevationMeters.toLocaleString("fr-FR")} m</span>
      </div>
      <p>Coupe verticale volontairement amplifiée pour être lisible. L’altitude provient du même raster V150 que les cases, sans relief fictif ajouté.</p>
    </div>
    <div className={styles.stats} data-testid="planet-traversal-stats-v154">
      <span>{grid.cells.length-blocked} case(s) praticables</span>
      <span>{blocked} obstacle(s) selon le profil</span>
      <span>{session.queued.length} étape(s) prévues</span>
      <span>{session.steps} pas accomplis</span>
      <span>{session.totalDistanceKm.toLocaleString("fr-FR")} km parcourus sur la carte</span>
    </div>
    <div className={styles.actions}>
      <button type="button" data-testid="planet-traversal-step-v154"
        disabled={!session.queued.length} onClick={advance}>Avancer d’une case</button>
      <button type="button" data-testid="planet-traversal-finish-v154"
        disabled={!session.queued.length} onClick={finish}>Parcourir l’itinéraire</button>
      <button type="button" data-testid="planet-traversal-reset-v154"
        onClick={reset}>Réinitialiser</button>
      <button type="button" data-testid="planet-traversal-json-v154"
        onClick={save}>Exporter l’exercice JSON</button>
    </div>
    <p className={styles.feedback} role="status" data-testid="planet-traversal-status-v154">{status}</p>
    <p>Code couleur : ◆ position du détachement, ● itinéraire préparé, ▲ pente infranchissable, ≈ milieu non terrestre. Les classes de mobilité sont des propositions originales à équilibrer par unité, et ne remplacent ni les transporteurs ni les liaisons militaires.</p>
  </div>;
}

export default function PlanetTraversalLabV154({planet,raster,slope,regionMask}:{
  planet:WarPlanetV96;raster:PlanetReliefRasterV150;
  slope:PlanetTerrainSlopeV152;regionMask:Uint8ClampedArray;
}) {
  const [territoryId,setTerritoryId]=useState(planet.territories[0]?.id??"");
  const territory=planet.territories.find(t=>t.id===territoryId)??planet.territories[0];
  const grid=useMemo(()=>territory?buildPlanetTraversalGridV154(raster,slope,regionMask,{
    worldCode:planet.id,longitude:territory.longitude,latitude:territory.latitude,
    width:19,height:13,samplePixels:1,
  }):null,[planet.id,territory,raster,slope,regionMask]);
  return <section className={styles.root} data-testid="planet-traversal-v154" data-world-code={planet.id}>
    <h5>Exercice interactif de franchissement des territoires</h5>
    <p>Prototype jouable isolé : choisir une unité Yautja existante, cliquer une destination et franchir les cases autorisées sans traverser artificiellement les mers, parois ou pentes impossibles.</p>
    {territory&&<label>Terrain territorial de départ
      <select data-testid="planet-traversal-territory-v154" value={territoryId}
        onChange={event=>setTerritoryId(event.target.value)}>
        {planet.territories.map(t=><option key={t.id} value={t.id}>
          {t.id} · {planet.definitions.find(item=>item.id===t.id)?.name??t.regionId}
        </option>)}
      </select>
    </label>}
    {grid?<WalkOnPlanetV154 key={planet.id+"-"+territoryId+"-"+raster.width}
      grid={grid} territoryName={territory?.id??""}/>:<p>Aucun territoire accessible pour cet exercice.</p>}
  </section>;
}

import {
 CLAN_WAR_COHERENT_VARIANTS_V126,type WarCoherentVariantV126,
} from "./clanWarWorldClimateV126";
import {
 createWarAiEncounterV126,type WarAiEncounterV126,type WarAiDetachmentV126,
} from "./clanWarEnemyProfilesV126";

export type WarMissionPhaseV127 = "recon"|"engage"|"objective"|"extract";
export type WarAiTriggerV127 =
 "initial-garrison"|"contact-confirmed"|"alarm-threshold"|"reinforcement-route-open"|"objective-contested";
export interface WarAiWaveV127{
 id:string;phase:WarMissionPhaseV127;trigger:WarAiTriggerV127;unitId:string;
 exactTeams:number;exactCombatants:number;role:string;lane:string;
 needsConnectedRoute:boolean;requiresPower:boolean;
 revealPolicy:"visible-on-entry"|"concealed-until-contact"|"report-only";
}
export interface WarStageRegionV127 {
 id:string;part:string;environment:string;terrain:string;fluid:string;
 coverType:string;climate:string;weather:string;mapScale:string;
 dimensions:"source-scale-unverified";
 weatherAllowed:boolean;
 hazard:string;hazardPolicy:string;
 naturalSnow:boolean;requirePowerForGate:boolean;
}
export interface WarAiTacticsV127{
 doctrine:string;enemyFaction:"rival-yautja-fan-fiction";
 neutralActors:"none-declared"|"noncombatants-possible";
 defend:string;attack:string;retreat:string;
 communications:string;powerFailure:string;
 objectivePriority:string;fogOfWar:string;
}
export interface WarEncounterSubVariantV127{
 id:string;sourceId:string;status:"design-only";schema:127;
 parentVersion:126;profile:1|2|3|4|5;players:number;
 worldId:string;worldKind:string;earthReferenceId:string|null;
 climate:string;phaseCount:4;
 sections:WarStageRegionV127[];
 enemyWaves:WarAiWaveV127[];
 estimatedEnemyTeams:number;estimatedEnemyPersons:number;
 maximumVisibleEnemies:number;hiddenOuterEstimate:number|null;
 sourceUnitPc:number;roleTypes:string[];
 mechanics:string[];tactics:WarAiTacticsV127;
 victoryConditions:string[];failureConditions:string[];
 missingAssets:string[];warnings:string[];
}
const PHASES:readonly WarMissionPhaseV127[]=["recon","engage","objective","extract"];
const SCENE_PARTS=[
 "accès à reconnaissance limitée","flanc derrière un couvert","nœud de l'objectif","issue de repli contrôlée",
] as const;
const WAVE_LANES=[
 "passe réellement connectée","porte latérale non condamnée",
 "rampe depuis la garnison","couloir extérieur contrôlé",
] as const;
function classifyCover(v:WarCoherentVariantV126):string {
 const c=v.environment.climate;
 if(c==="hot-desert")return "rochers de grès, talus sec, dépression hors crue";
 if(c==="polar"||c==="cold-desert")return "blocs de glace ou affleurements minéraux réellement stables";
 if(c==="marine")return "murets, rochers côtiers et plateformes de marée";
 if(c==="tropical-wet"||c==="wetland")return "racines épaisses et roches humides";
 if(c==="urban")return "structures construites (seulement là où la carte les atteste)";
 if(c==="volcanic")return "arêtes de basalte et écrans de cendre";
 return "couverts issus du matériau du site, à vérifier en collision";
}
function terrainHazard(v:WarCoherentVariantV126,section:number):string {
 const list=v.environment.hazards;
 return list[section%list.length]??"aucun événement certifié";
}
function powerRule(v:WarCoherentVariantV126):string {
 if(v.original.mode==="outer")return "Aucun coup de feu automatisé hors échéance de rapport.";
 return "Si la grille locale tombe, les portes et tourelles dépendantes de cette grille cessent d'agir. Les armes Yautja autonomes ne deviennent pas des appareils de réseau.";
}
function objectiveTactics(v:WarCoherentVariantV126):string{
 if(v.original.mode==="outer")return "Préserver les membres réels et différer le résultat jusqu'au rapport.";
 if(v.original.mode==="stealth")return "Protéger la preuve ou le dispositif, déclencher l'alerte après observation, non par omniscience.";
 if(v.original.mode==="assault")return "Réagir aux AP du joueur depuis les bastions existants, sans renfort gratuit.";
 return "Contester les vrais nœuds d'objectif et le ravitaillement ; une élimination seule ne valide pas une mission d'escorte.";
}
function neutralPolicy(v:WarCoherentVariantV126):WarAiTacticsV127["neutralActors"]{
 if(v.geography.worldKind==="earth")return "noncombatants-possible";
 const label=(v.original.referenceWork??"").toLowerCase();
 if(label.includes("alien"))return "noncombatants-possible";
 return "none-declared";
}
function waveTrigger(phase:WarMissionPhaseV127,mode:WarCoherentVariantV126["mode"]):WarAiTriggerV127{
 if(mode==="stealth"&&phase!=="recon")return "alarm-threshold";
 if(phase==="recon")return "initial-garrison";
 if(phase==="engage")return "contact-confirmed";
 if(phase==="objective")return "objective-contested";
 return "reinforcement-route-open";
}
export function buildWarEncounterSubVariantV127(
 scenario:WarCoherentVariantV126,profile:1|2|3|4|5,players=1,
):WarEncounterSubVariantV127{
 const ai=createWarAiEncounterV126(scenario,profile,players);
 const cover=classifyCover(scenario);
 const phases:WarStageRegionV127[]=PHASES.map((phase,index)=>({
  id:scenario.sourceId+"-REG-"+(index+1),part:SCENE_PARTS[index],
  environment:scenario.environment.biome,
  terrain:scenario.environment.terrain,fluid:scenario.environment.liquid,
  coverType:cover,climate:scenario.environment.climate,
  weather:scenario.environment.weather,mapScale:scenario.original.environment.mapScaleHint,
  dimensions:"source-scale-unverified",
  weatherAllowed:!scenario.environment.climate.includes("desert")||
    !/blizzard|neige chaude|givre tropical/i.test(scenario.environment.weather),
  hazard:terrainHazard(scenario,index),
  hazardPolicy:"Le danger n'est activé que si le terrain et le déclencheur existent réellement.",
  naturalSnow:scenario.environment.allowsNaturalSnow,requirePowerForGate:false,
 }));
 const groupWaves:WarAiWaveV127[]=ai.roleGroups.map((group:WarAiDetachmentV126,index)=>{
  const phase:WarMissionPhaseV127=group.activation==="start"?"recon":
   group.activation==="phase2"?"engage":
   group.activation==="phase3"?"objective":
   group.activation==="alarm"?"engage":"extract";
  const trigger=waveTrigger(phase,scenario.mode);
  return {
   id:group.id,phase,trigger,unitId:group.unitId,
   exactTeams:group.quantity,exactCombatants:group.expectedCombatants,
   role:group.role,lane:WAVE_LANES[index%4],
   needsConnectedRoute:phase!=="recon",requiresPower:false,
   revealPolicy:scenario.mode==="outer"?"report-only":
     phase==="recon"?"concealed-until-contact":"visible-on-entry",
  };
 });
 const mode=scenario.mode;
 const victoryConditions=mode==="assault"?
  ["bastion adverse réellement neutralisé","base alliée encore opérationnelle","rapport de bataille signé"]:
  mode==="outer"?["délai atteint","personnes et matériel réconciliés","rapport unique à l'arrivée"]:
  mode==="stealth"?["interaction d'objectif faite","route de repli franchie","alarme sous le seuil autorisé"]:
  ["occupation ou réparation d'objectif réel","effectifs vivants sur la zone","route de retrait non fictive"];
 const failureConditions=mode==="outer"?
  ["rapport manquant","détachement invalide ou déjà affecté","route réellement impraticable"]:
  ["aucun combattant admissible","objectif non tenu","issue bloquée ou phase expirée"];
 const siteNeeds=scenario.geography.worldKind==="earth"?[
   "vecteurs terrain terrestre et relief à vérifier, WGS84",
   "couvrants de "+scenario.environment.biome+" réellement présents",
   "matière de sol "+scenario.environment.terrain,
   "eau/hydrologie "+scenario.environment.liquid,
   "modèles de bâtiments d'époque uniquement si autorisés par la source",
   "sprites W3-U identifiés dans la continuité du jeu",
  ]:[
   ...scenario.original.production.neededSprites,
   ...scenario.original.production.neededTiles,
   "révision des effets de météo pour "+scenario.environment.climate,
  ];
 const warnings=[...ai.warnings,...scenario.auditWarnings];
 if(scenario.geography.worldKind==="unresolved-fiction")
  warnings.push("Épisode non localisable : interdit de le traiter comme territoire de campagne");
 if(scenario.geography.worldKind==="earth"&&scenario.geography.latitude===null)
  warnings.push("Référence terrestre sans coordonnées attestées : scène exacte non plaçable");
 if(mode==="outer")warnings.push("Adversaires non révélés aux clients avant la fin du mandat");
 return {
  id:scenario.sourceId+"-P"+profile,sourceId:scenario.sourceId,
  status:"design-only",schema:127,parentVersion:126,profile,players,
  worldId:scenario.geography.worldId,worldKind:scenario.geography.worldKind,
  earthReferenceId:scenario.geography.earthSiteId,
  climate:scenario.environment.climate,phaseCount:4,sections:phases,
  enemyWaves:groupWaves,estimatedEnemyTeams:ai.totalTeams,
  estimatedEnemyPersons:ai.totalCombatants,
  maximumVisibleEnemies:ai.maxSimultaneous,
  hiddenOuterEstimate:mode==="outer"?ai.totalTeams:null,
  sourceUnitPc:ai.difficultyBudgetPc,roleTypes:[...new Set(groupWaves.map(w=>w.unitId))],
  mechanics:scenario.original.operation.dynamicPhases,
  tactics:{
   doctrine:ai.doctrine,enemyFaction:"rival-yautja-fan-fiction",
   neutralActors:neutralPolicy(scenario),
   defend:mode==="rts"?"Contester la zone avec les mêmes collisions que les joueurs":"Protéger les points réellement reconnus",
   attack:ai.objectiveCounterplay,
   retreat:"Se retirer par une liaison validée, sans téléportation de réserve",
   communications:"Une escouade cachée ne voit pas à travers les murs ni l'ensemble du globe",
   powerFailure:powerRule(scenario),
   objectivePriority:objectiveTactics(scenario),
   fogOfWar:ai.visibility,
  },victoryConditions,failureConditions,
  missingAssets:[
   ...siteNeeds,
   "placements et chemins d'accès réels de la carte",
   "règles de collision/abri du terrain",
  ],
  warnings,
 };
}
export function warEncounterSubVariantsV127(scenario:WarCoherentVariantV126){
 return ([1,2,3,4,5] as const).map(index=>buildWarEncounterSubVariantV127(scenario,index));
}
export function auditWarEncounterSubVariantsV127(){
 const seen=new Set<string>(),errors:string[]=[];let total=0,phases=0,groups=0;
 for(const scenario of CLAN_WAR_COHERENT_VARIANTS_V126){
  for(const preset of warEncounterSubVariantsV127(scenario)){
   total++;phases+=preset.sections.length;groups+=preset.enemyWaves.length;
   if(seen.has(preset.id))errors.push("Dupe "+preset.id);
   seen.add(preset.id);
   if(preset.sections.length!==4)errors.push("Not four phases: "+preset.id);
   if(preset.enemyWaves.some(g=>g.exactCombatants<1||!/^W3-U\d{2}$/.test(g.unitId)))
    errors.push("Invalid roster: "+preset.id);
   if(preset.sourceUnitPc<0||preset.estimatedEnemyTeams<0)errors.push("Negative units "+preset.id);
   if(scenario.mode==="outer"&&preset.enemyWaves.length)errors.push("Leaked Outer Ops opponents "+preset.id);
   if(preset.sections.some(s=>!s.weatherAllowed))errors.push("Illegal weather "+preset.id);
  }
 }
 if(total!==6000||phases!==24000)errors.push("Missing 5 × 4 phases over 1200 contracts");
 return {sourceMissions:1200,subVariants:total,sceneSections:phases,authoredGroupAssignments:groups,errors};
}

import {type ClanWarVariantV120} from "./clanWarVariantAtlasV120";
import {CLAN_WAR_COHERENT_VARIANTS_V126,type WarCoherentVariantV126} from "./clanWarWorldClimateV126";

export type WarAiDoctrineV126="cautious"|"balanced"|"aggressive"|"defensive"|"reinforcement";
export type WarAiRoleV126="recon"|"guard"|"assault"|"heavy"|"support"|"specialist";
export interface WarAiDetachmentV126 {
